package com.hs.jxc.sys.service;

import com.hs.jxc.common.api.*;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.db.DbRows;
import com.hs.jxc.sys.api.Access;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.*;

/** Watchers are restricted observations; delegation does not transfer a role or data scope. */
@Service @Transactional
public class DocumentGovernanceService {
    private final JdbcTemplate jdbc;private final AuthorizationService auth;private final DocumentAccessService docs;private final FieldPolicyService fields;private final JsonCodec json;private final AuditWriter audit;private final CountryLifecycle lifecycle;
    public DocumentGovernanceService(JdbcTemplate jdbc,AuthorizationService auth,DocumentAccessService docs,FieldPolicyService fields,JsonCodec json,AuditWriter audit,CountryLifecycle lifecycle){this.jdbc=jdbc;this.auth=auth;this.docs=docs;this.fields=fields;this.json=json;this.audit=audit;this.lifecycle=lifecycle;}
    private Access actor(RequestContext c,boolean write){var a=write?auth.authorizePolicyWrite(c,false):auth.authorize(c);a.requireCountry();return a;}
    public Map<String,Object> watchers(RequestContext c,Map<String,String>q){var a=actor(c,false);a.require("sys:watcher:edit");return page(jdbc.queryForList("SELECT w.*,u.display_name AS user_name,wh.name AS warehouse_name FROM sys_doc_watcher w JOIN sys_user u ON u.id=w.user_id LEFT JOIN org_warehouse wh ON wh.country_id=w.country_id AND wh.id=w.warehouse_id WHERE w.country_id=? ORDER BY w.id DESC",a.requireCountry()).stream().filter(r->visible(a,r)).map(this::watchOut).toList(),q);}
    public Map<String,Object> watcher(RequestContext c,long id){var a=actor(c,false);a.require("sys:watcher:edit");var r=watchRow(a,id,false);return watchOut(r);}
    private Map<String,Object>watchRow(Access a,long id,boolean lock){var rs=jdbc.queryForList("SELECT * FROM sys_doc_watcher WHERE country_id=? AND id=?"+(lock?" FOR UPDATE":""),a.requireCountry(),id);if(rs.isEmpty()||!visible(a,rs.getFirst()))throw ApiException.notFound();return rs.getFirst();}
    private boolean visible(Access a,Map<String,Object>r){if(a.scope().all())return true;String target=String.valueOf(r.get("target_type"));if(target.equals("DOC"))try{docs.requireDocumentAccess(a,String.valueOf(r.get("doc_type")),((Number)r.get("doc_id")).longValue(),false);return true;}catch(ApiException e){if(e.getStatus()!=403&&e.getStatus()!=404)throw e;return false;}return target.equals("WAREHOUSE_RULE")&&a.scope().warehouses().contains(((Number)r.get("warehouse_id")).longValue());}
    private Map<String,Object> watchOut(Map<String,Object>r){var out=DbRows.camel(r);out.put("fieldGroups",json.read(String.valueOf(r.get("field_groups")),List.class));return out;}
    public Map<String,Object>saveWatcher(RequestContext c,Long id,Map<String,Object>b){var a=actor(c,true);a.require("sys:watcher:edit");lifecycle.requireConfigurationWritable(a);var old=id==null?null:watchRow(a,id,true);var merged=new LinkedHashMap<String,Object>();if(old!=null)merged.putAll(watchOut(old));merged.putAll(b);String type=Inputs.required(merged,"docType"),watch=Inputs.required(merged,"watchType"),target=Inputs.required(merged,"targetType");if(!docs.supports(type)||!Set.of("VIEWER","CC").contains(watch)||!Set.of("DOC","WAREHOUSE_RULE","DOC_TYPE_RULE").contains(target))throw Inputs.bad("看单或抄送规则不合法");long user=Inputs.id(merged.get("userId"));var subject=auth.accessForSubject(a,user);Long doc=merged.get("docId")==null?null:Inputs.id(merged.get("docId")),wh=merged.get("warehouseId")==null?null:Inputs.id(merged.get("warehouseId"));if(target.equals("DOC")){if(doc==null)throw Inputs.bad("请选择单据");docs.requireDocumentAccess(a,type,doc,false);}else if(target.equals("WAREHOUSE_RULE")){if(wh==null)throw Inputs.bad("请选择仓库");var rows=jdbc.queryForList("SELECT id AS warehouse_id,country_id,entity_id,store_id FROM org_warehouse WHERE country_id=? AND id=?",a.requireCountry(),wh);if(rows.isEmpty())throw ApiException.notFound();a.requireRow(DbRows.camel(rows.getFirst()));}else if(!a.scope().all())throw ApiException.forbidden();
        var groups=SystemManagementService.strings(merged.getOrDefault("fieldGroups",List.of()));for(String g:groups)if(!FieldPolicyService.GROUPS.contains(g)||FieldPolicyService.rank(a.fieldGroups().get(g))<1||FieldPolicyService.rank(subject.fieldGroups().get(g))<1)throw ApiException.forbidden();
        long result;if(id==null)result=jdbc.queryForObject("INSERT INTO sys_doc_watcher(country_id,watch_type,target_type,doc_type,doc_id,warehouse_id,user_id,field_groups,created_by) VALUES(?,?,?,?,?,?,?,?::jsonb,?) RETURNING id",Long.class,a.requireCountry(),watch,target,type,doc,wh,user,json.write(groups),a.userId());else{if(jdbc.update("UPDATE sys_doc_watcher SET watch_type=?,target_type=?,doc_type=?,doc_id=?,warehouse_id=?,user_id=?,field_groups=?::jsonb,version=version+1 WHERE country_id=? AND id=? AND version=?",watch,target,type,doc,wh,user,json.write(groups),a.requireCountry(),id,Inputs.version(b))!=1)throw Inputs.conflict();result=id;}var out=watchOut(watchRow(a,result,false));audit.append(c,"配置看单与抄送","doc-watcher",result,old,out);auth.bump(a.requireCountry());return out;
    }
    public Map<String,Object>toggleWatcher(RequestContext c,long id,boolean enabled){var a=actor(c,true);a.require("sys:watcher:edit");lifecycle.requireConfigurationWritable(a);var old=watchRow(a,id,true);jdbc.update("UPDATE sys_doc_watcher SET status=?,version=version+1 WHERE country_id=? AND id=?",enabled?"ENABLED":"DISABLED",a.requireCountry(),id);var out=watchOut(watchRow(a,id,false));auth.bump(a.requireCountry());audit.append(c,enabled?"启用看单规则":"停用看单规则","doc-watcher",id,old,out);return out;}
    public Map<String,Object>delegations(RequestContext c,Map<String,String>q){var a=actor(c,false);return page(jdbc.queryForList("SELECT d.*,f.display_name from_user_name,t.display_name to_user_name FROM sys_delegation d JOIN sys_user f ON f.id=d.from_user_id JOIN sys_user t ON t.id=d.to_user_id WHERE d.country_id=? AND (d.from_user_id=? OR d.to_user_id=?) ORDER BY d.id DESC",a.requireCountry(),a.userId(),a.userId()).stream().map(r->{var out=DbRows.camel(r);out.put("scope",json.read(String.valueOf(r.get("scope")),List.class));out.put("canRevoke",((Number)r.get("from_user_id")).longValue()==a.userId());if("ACTIVE".equals(r.get("status"))&&!((Timestamp)r.get("end_at")).toInstant().isAfter(Instant.now()))out.put("status","EXPIRED");return out;}).toList(),q);}
    public Map<String,Object>delegate(RequestContext c,Map<String,Object>b){var a=actor(c,true);lifecycle.requireConfigurationWritable(a);long to=Inputs.id(b.get("toUserId"));if(to==a.userId())throw Inputs.bad("不能给自己设置审批代理");auth.accessForSubject(a,to);var types=SystemManagementService.strings(b.getOrDefault("scope",b.getOrDefault("docTypes",List.of())));if(types.isEmpty()||types.stream().anyMatch(t->!docs.supports(t)))throw Inputs.bad("请选择已注册单据类型");Instant now=jdbc.queryForObject("SELECT clock_timestamp()",(rs,n)->rs.getTimestamp(1).toInstant()),start=date(b.get("startAt"),now),end=date(b.get("endAt"),null);if(end==null||!end.isAfter(start))throw Inputs.bad("代理授权必须有明确的结束时间且晚于开始");String reason=Inputs.required(b,"reason");long id=jdbc.queryForObject("INSERT INTO sys_delegation(country_id,from_user_id,to_user_id,scope,start_at,end_at,reason) VALUES(?,?,?,?::jsonb,?,?,?) RETURNING id",Long.class,a.requireCountry(),a.userId(),to,json.write(types),Timestamp.from(start),Timestamp.from(end),reason);auth.bump(a.requireCountry());var out=DbRows.camel(jdbc.queryForMap("SELECT * FROM sys_delegation WHERE country_id=? AND id=?",a.requireCountry(),id));audit.append(c,"设置限时审批代理","delegation",id,null,out);return out;}
    public Map<String,Object>revoke(RequestContext c,long id){var a=actor(c,true);var rs=jdbc.queryForList("SELECT * FROM sys_delegation WHERE country_id=? AND id=? AND from_user_id=? FOR UPDATE",a.requireCountry(),id,a.userId());if(rs.isEmpty())throw ApiException.notFound();jdbc.update("UPDATE sys_delegation SET status='REVOKED',version=version+1 WHERE country_id=? AND id=?",a.requireCountry(),id);auth.bump(a.requireCountry());audit.append(c,"撤销审批代理","delegation",id,rs.getFirst(),Map.of("status","REVOKED"));return Map.of("id",id,"status","REVOKED");}
    /** SQL fragment only uses trusted identifiers from WorkflowService, never user SQL. */
    public static String taskVisibility(){return "(t.assignee_id=? OR EXISTS(SELECT 1 FROM sys_delegation d WHERE d.country_id=t.country_id AND d.from_user_id=t.assignee_id AND d.to_user_id=? AND d.status='ACTIVE' AND d.start_at<=clock_timestamp() AND d.end_at>clock_timestamp() AND jsonb_exists(d.scope,i.doc_type)))";}
    public void requireTaskAuthority(Access a,Map<String,Object>task,String type,long doc){long assignee=((Number)task.get("assignee_id")).longValue();if(assignee==a.userId())return;var delegations=jdbc.queryForList("SELECT * FROM sys_delegation WHERE country_id=? AND from_user_id=? AND to_user_id=? AND status='ACTIVE' AND start_at<=clock_timestamp() AND end_at>clock_timestamp() AND jsonb_exists(scope,?) FOR SHARE",a.requireCountry(),assignee,a.userId(),type);if(delegations.isEmpty())throw ApiException.notFound();var original=auth.accessForSubject(a,assignee);docs.requireDocumentAccess(original,type,doc,false);docs.requireDocumentAccess(a,type,doc,false);Instant until=delegations.stream().map(d->((Timestamp)d.get("end_at")).toInstant()).max(Instant::compareTo).orElseThrow();TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void beforeCommit(boolean readOnly){Instant now=jdbc.queryForObject("SELECT clock_timestamp()",(rs,n)->rs.getTimestamp(1).toInstant());if(!now.isBefore(until))throw new ApiException(403,"SYS_FORBIDDEN","代理授权已到期");}});}
    public void notifyCc(Access actor,String type,long docId,Map<String,Object>source){for(var row:jdbc.queryForList("SELECT * FROM sys_doc_watcher WHERE country_id=? AND watch_type='CC' AND status='ENABLED' AND doc_type=?",actor.requireCountry(),type)){String target=String.valueOf(row.get("target_type"));if(target.equals("DOC")&&((Number)row.get("doc_id")).longValue()!=docId)continue;if(target.equals("WAREHOUSE_RULE")&&!Objects.equals(row.get("warehouse_id"),source.get("warehouseId")))continue;long user=((Number)row.get("user_id")).longValue();try{var subject=auth.accessForSubject(actor,user);docs.requireDocumentAccess(subject,type,docId,false);jdbc.update("INSERT INTO sys_todo(country_id,todo_type,dedup_key,title,link,assignee_id) VALUES(?,'WORKFLOW_CC',?,?,'/workbench',?) ON CONFLICT(country_id,dedup_key) DO NOTHING",actor.requireCountry(),"WF_CC:"+type+":"+docId+":"+user,"有一条 "+type+" 单据抄送，请按当前权限查看",user);}catch(ApiException e){if(!Set.of(401,403,404).contains(e.getStatus()))throw e;}}}
    private Instant date(Object value,Instant fallback){if(value==null||value.toString().isBlank())return fallback;try{return Instant.parse(value.toString());}catch(Exception e){throw Inputs.bad("代理时间必须含时区");}}
    private Map<String,Object>page(List<Map<String,Object>>rows,Map<String,String>q){int page=1,size=20;try{page=Integer.parseInt(q.getOrDefault("page","1"));size=Integer.parseInt(q.getOrDefault("size","20"));}catch(Exception e){throw Inputs.bad("分页参数不合法");}if(page<1||size<1||size>200)throw Inputs.bad("分页参数不合法");int from=Math.min(rows.size(),(page-1)*size);return Map.of("records",rows.subList(from,Math.min(rows.size(),from+size)),"total",rows.size(),"page",page,"size",size);}
}
